System.Collections.IEnumerator Check(){
yield return new UnityEngine.WaitForSeconds(2);
var cube=UnityEngine.GameObject.Find("NaturePlayerCube");var body=cube.GetComponent<UnityEngine.Rigidbody>();var cam=UnityEngine.Camera.main;var start=body.position;var cameraStart=cam.transform.position;var joy=UnityEngine.Object.FindFirstObjectByType<FixedJoystick>();var rt=(UnityEngine.RectTransform)joy.transform;var center=UnityEngine.RectTransformUtility.WorldToScreenPoint(null,rt.position);var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=center+UnityEngine.Vector2.right*140*joy.GetComponentInParent<UnityEngine.Canvas>().scaleFactor};joy.OnPointerDown(e);
yield return new UnityEngine.WaitForSeconds(.8f);joy.OnPointerUp(e);yield return new UnityEngine.WaitForSeconds(1.5f);
var delta=body.position-start;var horizontal=new UnityEngine.Vector2(delta.x,delta.z).magnitude;var stopSpeed=new UnityEngine.Vector2(body.linearVelocity.x,body.linearVelocity.z).magnitude;var camDelta=UnityEngine.Vector3.Distance(cameraStart,cam.transform.position);var mist=cam.GetComponent<MistFilterEffect>();
System.IO.File.WriteAllText("Temp/NatureStageCheck.txt","distance="+horizontal+"\nstopSpeed="+stopSpeed+"\ncameraFollowDistance="+camDelta+"\nheight="+body.position.y+"\nmistPasses="+mist.mistFilterShader.passCount+"\nactiveCamera="+cam.GetComponent<Unity.Cinemachine.CinemachineBrain>().ActiveVirtualCamera.Name);
body.position=start;body.linearVelocity=UnityEngine.Vector3.zero;yield return new UnityEngine.WaitForSeconds(2);UnityEngine.ScreenCapture.CaptureScreenshot("Screenshots/NatureStage.png");}
UnityEngine.Object.FindFirstObjectByType<HundredHour.JoystickDemo.JoystickCubeMover>().StartCoroutine(Check());return "Checking input, motion, camera and mist";
